CREATE TEMP TABLE curriculum_revised (payload jsonb NOT NULL) ON COMMIT DROP;
INSERT INTO curriculum_revised(payload) VALUES ($guide_payload$[{"slug":"talora-digital-marketing-2026","task_number":1,"title":"Audience Research","old_instructions":"[[AZ]]\n## Məqsəd\nNümunə məhsul seç ;  İki auditoriya seqmenti təsvir et ;  Nəticələri açıq mənbələrlə əsaslandır.\n\n## Addım-addım icra\n1. Nümunə məhsul seç.\n2. İki auditoriya seqmenti təsvir et.\n3. Nəticələri açıq mənbələrlə əsaslandır.\n4. Nəticəni yoxla, fərziyyələri və məlumat mənbələrini qeyd et.\n\n## Nə təhvil verilməlidir?\nAudience research brief. Fayl və ya oxuna bilən link, 3–5 cümləlik izah və istifadə edilən mənbələr.\n\n## Qəbul meyarları\nBütün üç addımın nəticəsi artefaktda görünür, verilən nümunələr təkrar yoxlana bilir, uydurma fakt və icazəsiz şəxsi məlumat yoxdur.\n\n[[EN]]\n## Goal\nChoose a sample product ;  Define two audience segments ;  Support assumptions with public sources.\n\n## Step-by-step\n1. Choose a sample product.\n2. Define two audience segments.\n3. Support assumptions with public sources.\n4. Verify the result; document assumptions and sources.\n\n## Deliverables\nAudience research brief. Submit a readable file/link, a short explanation and credited sources.\n\n## Acceptance criteria\nEvidence supports all three steps, examples can be reviewed, and no fabricated facts or unauthorized personal data are included.","old_description":"[[AZ]]\nNümunə məhsul seç ;  İki auditoriya seqmenti təsvir et ;  Nəticələri açıq mənbələrlə əsaslandır.\n\n[[EN]]\nChoose a sample product ;  Define two audience segments ;  Support assumptions with public sources.","new_instructions":"[[AZ]]\n## Tapşırığın məqsədi: Audience Research\nBu tapşırıq birinci dəfə bu sahəni öyrənən tələbə üçün praktik işdir. Reklam büdcəsi tələb edilmir: məlumatı sintetik və ya mənbəli olaraq göstər.\n**Nümunə situasiya:** Tələbə tədbir platforması üçün iki persona və ehtiyacları araşdır; hipotezi fakt kimi göstərmə.\n\n## Hansı pulsuz alətlər lazımdır?\n- **Google Docs** — https://docs.google.com/document/. Boş sənəd aç, başlıqları və cədvəlləri doldur, PDF kimi yüklə.\n- **Google Trends** — https://trends.google.com. Axtarış ifadəsini yaz, bölgəni seç; indeks göstəricisini real axtarış sayı sayma.\n> Heç bir pullu abunə, reklam büdcəsi və ya API açarı tələb olunmur. Free plan limiti bitdikdə lokal alternativdən istifadə et. Başqa şəxslərin şifrəsini, şəxsi məlumatını və icazəsiz fayllarını paylaşma.\n\n## Addım-addım icra təlimatı\n1. Öz iş qovluğunu yarat: Talora / Digital Marketing / Task-1. Əvvəlki tapşırıqların nəticəsi varsa onlardan istifadə et; yoxdursa 5 sintetik nümunə sətri hazırla.\n2. Bu tapşırığın məqsədini və istifadəçisini bir cümlədə yaz; nümunədə hansı nəticənin uğur sayılacağını müəyyən et.\n3. Nümunə məhsul seç. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n4. İki auditoriya seqmenti təsvir et. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n5. Nəticələri açıq mənbələrlə əsaslandır. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n6. Nümunəni işlə: Tələbə tədbir platforması üçün iki persona və ehtiyacları araşdır; hipotezi fakt kimi göstərmə. Hansı məqamın düzgün işlədiyini və hansı məhdudiyyətin qaldığını ayrıca izah et.\n7. Əsas artefaktı hazırla: Audience research brief. Oxuna bilən PDF/fayl və ya paylaşılabilən linki yoxla; redaktə edilən orijinalı da saxla.\n8. Öz işini təkrar yoxla. Üç əsas addımı bitirdiyini göstər; 3–5 cümləlik nəticə, istifadə olunan alətlər və mənbələri qeyd et.\n\n## İşlənmiş nümunə necə görünməlidir?\nTələbə tədbir platforması üçün iki persona və ehtiyacları araşdır; hipotezi fakt kimi göstərmə.\nBu nümunəni olduğu kimi kopyalama: öz sintetik ssenarinə uyğun doldur, araşdırdığın faktları və fərziyyələri ayır.\n\n## Nə təhvil verməlisən?\n- **Əsas nəticə:** Audience research brief.\n- **Sübut:** oxunan fayl və ya link; uyğun olduqda PDF, cədvəl, PNG, SVG, MP4, SRT, kod və ya layihə faylı.\n- **Qısa hesabat:** 3–5 cümlədə nə etdin, niyə bu üsulu seçdin, nəyi yoxladın?\n- **Mənbələr:** istinadlar, istifadə etdiyin vizual/audio materialın icazəsi.\n\n## Qiymətləndirmə meyarları (100 bal)\n- **40 bal:** Üç əsas fəaliyyətin hər biri real nəticədə görünür.\n- **25 bal:** Nümunə və məntiq yoxlanılıb, nəticə təkrarlana bilir.\n- **15 bal:** Fayl oxunaqlı, düzgün adlandırılıb və bölmələr aydındır.\n- **10 bal:** Məxfilik, müəlliflik və pulsuz istifadə qaydaları gözlənilib.\n- **10 bal:** Öz sözlərinlə yekun və mümkün təkmilləşdirmə izah olunub.\n\n## Göndərməzdən əvvəl yoxla\n- Demo nəticəni real kampaniya nəticəsi adlandırma.\n- Link başqa şəxsə oxu icazəsi verir, amma sənədin içində şəxsi məlumat və şifrə yoxdur.\n- Lazım olan hissələr sadəcə nəzəri cümlələr deyil, təqdim etdiyin real artefaktla sübut olunur.\n- Ödəniş qəbzi və ya Pro alət tələb olunmur.\n\n[[EN]]\n## Assignment goal: Audience Research\nThis practical assignment is designed for beginners. No ad spend is necessary: use labeled synthetic or cited public data.\n**Example scenario:** Research two personas for a student-events platform and label assumptions.\n\n## Free tools and platforms\n- **Google Docs** — https://docs.google.com/document/. Create a blank document, organize headings/tables and export PDF.\n- **Google Trends** — https://trends.google.com. Enter a query and region; the interest index is not absolute search volume.\n> No paid subscriptions, ad budgets or paid API keys are required. If a free quota is exhausted, choose a local alternative. Never share passwords, personal data or assets you cannot legally reuse.\n\n## Step-by-step guide\n1. Set up your work folder: Talora / Digital Marketing / Task-1. Reuse your earlier fictional artifacts or create five sample records.\n2. Explain the objective and intended user in one sentence; define what success would look like.\n3. Choose a sample product. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n4. Define two audience segments. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n5. Support assumptions with public sources. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n6. Work through the scenario: Research two personas for a student-events platform and label assumptions. Document what worked and any limitations.\n7. Complete the main artifact: Audience research brief. Verify that a reader can open the PDF/file or shared link; keep the editable source too.\n8. Review all three essential actions, then write a three-to-five sentence conclusion listing tools, sources and improvements.\n\n## A worked example\nResearch two personas for a student-events platform and label assumptions.\nDo not copy the example unchanged; adapt it to your own fictional scenario and distinguish evidence from assumptions.\n\n## What you must submit\n- **Primary artifact:** Audience research brief.\n- **Evidence:** a readable file/link or appropriate PDF, spreadsheet, PNG, SVG, MP4, SRT, source code or project file.\n- **Short report:** three to five sentences about your approach, what you verified and why.\n- **Sources:** citations and usage rights for images, audio or reused text.\n\n## Scoring rubric (100 points)\n- **40 points:** all three core actions are shown in the submitted work.\n- **25 points:** tested, accurate, reproducible result or example.\n- **15 points:** readable structure, proper filenames and export format.\n- **10 points:** privacy, licensing and free-tool rules followed.\n- **10 points:** your explanation and suggested improvements.\n\n## Final checklist\n- Never describe mock metrics as actual campaign results.\n- Test file permissions; never expose credentials or private data.\n- Provide practical evidence, not theory alone.\n- Do not pay for premium features to complete the task.","new_description":"[[AZ]]\nAudience Research: Nümunə məhsul seç. İki auditoriya seqmenti təsvir et. Nəticələri açıq mənbələrlə əsaslandır. Pulsuz alətlər: Google Docs, Google Trends. Nəticə: Audience research brief.\n\n[[EN]]\nAudience Research: Choose a sample product. Define two audience segments. Support assumptions with public sources. Free tools: Google Docs, Google Trends. Output: Audience research brief."},{"slug":"talora-digital-marketing-2026","task_number":2,"title":"Competitor Benchmark","old_instructions":"[[AZ]]\n## Məqsəd\nÜç rəqibin açıq kanallarını araşdır ;  Mövqe və mesajları müqayisə et ;  Fərqləndirmə imkanını yaz.\n\n## Addım-addım icra\n1. Üç rəqibin açıq kanallarını araşdır.\n2. Mövqe və mesajları müqayisə et.\n3. Fərqləndirmə imkanını yaz.\n4. Nəticəni yoxla, fərziyyələri və məlumat mənbələrini qeyd et.\n\n## Nə təhvil verilməlidir?\nCompetitor matrix. Fayl və ya oxuna bilən link, 3–5 cümləlik izah və istifadə edilən mənbələr.\n\n## Qəbul meyarları\nBütün üç addımın nəticəsi artefaktda görünür, verilən nümunələr təkrar yoxlana bilir, uydurma fakt və icazəsiz şəxsi məlumat yoxdur.\n\n[[EN]]\n## Goal\nAnalyze three competitors' public channels ;  Compare positioning and messages ;  Identify a differentiation opportunity.\n\n## Step-by-step\n1. Analyze three competitors' public channels.\n2. Compare positioning and messages.\n3. Identify a differentiation opportunity.\n4. Verify the result; document assumptions and sources.\n\n## Deliverables\nCompetitor matrix. Submit a readable file/link, a short explanation and credited sources.\n\n## Acceptance criteria\nEvidence supports all three steps, examples can be reviewed, and no fabricated facts or unauthorized personal data are included.","old_description":"[[AZ]]\nÜç rəqibin açıq kanallarını araşdır ;  Mövqe və mesajları müqayisə et ;  Fərqləndirmə imkanını yaz.\n\n[[EN]]\nAnalyze three competitors' public channels ;  Compare positioning and messages ;  Identify a differentiation opportunity.","new_instructions":"[[AZ]]\n## Tapşırığın məqsədi: Competitor Benchmark\nBu tapşırıq birinci dəfə bu sahəni öyrənən tələbə üçün praktik işdir. Reklam büdcəsi tələb edilmir: məlumatı sintetik və ya mənbəli olaraq göstər.\n**Nümunə situasiya:** Üç oxşar açıq saytın mesaj, CTA və kontentini cədvəldə müqayisə et.\n\n## Hansı pulsuz alətlər lazımdır?\n- **Google Sheets** — https://sheets.google.com. Yeni cədvəl yarat, sütun adlarını və ən azı 5 sətirlik nümunəni daxil et.\n> Heç bir pullu abunə, reklam büdcəsi və ya API açarı tələb olunmur. Free plan limiti bitdikdə lokal alternativdən istifadə et. Başqa şəxslərin şifrəsini, şəxsi məlumatını və icazəsiz fayllarını paylaşma.\n\n## Addım-addım icra təlimatı\n1. Öz iş qovluğunu yarat: Talora / Digital Marketing / Task-2. Əvvəlki tapşırıqların nəticəsi varsa onlardan istifadə et; yoxdursa 5 sintetik nümunə sətri hazırla.\n2. Bu tapşırığın məqsədini və istifadəçisini bir cümlədə yaz; nümunədə hansı nəticənin uğur sayılacağını müəyyən et.\n3. Üç rəqibin açıq kanallarını araşdır. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n4. Mövqe və mesajları müqayisə et. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n5. Fərqləndirmə imkanını yaz. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n6. Nümunəni işlə: Üç oxşar açıq saytın mesaj, CTA və kontentini cədvəldə müqayisə et. Hansı məqamın düzgün işlədiyini və hansı məhdudiyyətin qaldığını ayrıca izah et.\n7. Əsas artefaktı hazırla: Competitor matrix. Oxuna bilən PDF/fayl və ya paylaşılabilən linki yoxla; redaktə edilən orijinalı da saxla.\n8. Öz işini təkrar yoxla. Üç əsas addımı bitirdiyini göstər; 3–5 cümləlik nəticə, istifadə olunan alətlər və mənbələri qeyd et.\n\n## İşlənmiş nümunə necə görünməlidir?\nÜç oxşar açıq saytın mesaj, CTA və kontentini cədvəldə müqayisə et.\nBu nümunəni olduğu kimi kopyalama: öz sintetik ssenarinə uyğun doldur, araşdırdığın faktları və fərziyyələri ayır.\n\n## Nə təhvil verməlisən?\n- **Əsas nəticə:** Competitor matrix.\n- **Sübut:** oxunan fayl və ya link; uyğun olduqda PDF, cədvəl, PNG, SVG, MP4, SRT, kod və ya layihə faylı.\n- **Qısa hesabat:** 3–5 cümlədə nə etdin, niyə bu üsulu seçdin, nəyi yoxladın?\n- **Mənbələr:** istinadlar, istifadə etdiyin vizual/audio materialın icazəsi.\n\n## Qiymətləndirmə meyarları (100 bal)\n- **40 bal:** Üç əsas fəaliyyətin hər biri real nəticədə görünür.\n- **25 bal:** Nümunə və məntiq yoxlanılıb, nəticə təkrarlana bilir.\n- **15 bal:** Fayl oxunaqlı, düzgün adlandırılıb və bölmələr aydındır.\n- **10 bal:** Məxfilik, müəlliflik və pulsuz istifadə qaydaları gözlənilib.\n- **10 bal:** Öz sözlərinlə yekun və mümkün təkmilləşdirmə izah olunub.\n\n## Göndərməzdən əvvəl yoxla\n- Demo nəticəni real kampaniya nəticəsi adlandırma.\n- Link başqa şəxsə oxu icazəsi verir, amma sənədin içində şəxsi məlumat və şifrə yoxdur.\n- Lazım olan hissələr sadəcə nəzəri cümlələr deyil, təqdim etdiyin real artefaktla sübut olunur.\n- Ödəniş qəbzi və ya Pro alət tələb olunmur.\n\n[[EN]]\n## Assignment goal: Competitor Benchmark\nThis practical assignment is designed for beginners. No ad spend is necessary: use labeled synthetic or cited public data.\n**Example scenario:** Compare messaging, calls to action and content on three public competitor sites.\n\n## Free tools and platforms\n- **Google Sheets** — https://sheets.google.com. Create a sheet, name the columns and add at least five fictional rows.\n> No paid subscriptions, ad budgets or paid API keys are required. If a free quota is exhausted, choose a local alternative. Never share passwords, personal data or assets you cannot legally reuse.\n\n## Step-by-step guide\n1. Set up your work folder: Talora / Digital Marketing / Task-2. Reuse your earlier fictional artifacts or create five sample records.\n2. Explain the objective and intended user in one sentence; define what success would look like.\n3. Analyze three competitors' public channels. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n4. Compare positioning and messages. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n5. Identify a differentiation opportunity. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n6. Work through the scenario: Compare messaging, calls to action and content on three public competitor sites. Document what worked and any limitations.\n7. Complete the main artifact: Competitor matrix. Verify that a reader can open the PDF/file or shared link; keep the editable source too.\n8. Review all three essential actions, then write a three-to-five sentence conclusion listing tools, sources and improvements.\n\n## A worked example\nCompare messaging, calls to action and content on three public competitor sites.\nDo not copy the example unchanged; adapt it to your own fictional scenario and distinguish evidence from assumptions.\n\n## What you must submit\n- **Primary artifact:** Competitor matrix.\n- **Evidence:** a readable file/link or appropriate PDF, spreadsheet, PNG, SVG, MP4, SRT, source code or project file.\n- **Short report:** three to five sentences about your approach, what you verified and why.\n- **Sources:** citations and usage rights for images, audio or reused text.\n\n## Scoring rubric (100 points)\n- **40 points:** all three core actions are shown in the submitted work.\n- **25 points:** tested, accurate, reproducible result or example.\n- **15 points:** readable structure, proper filenames and export format.\n- **10 points:** privacy, licensing and free-tool rules followed.\n- **10 points:** your explanation and suggested improvements.\n\n## Final checklist\n- Never describe mock metrics as actual campaign results.\n- Test file permissions; never expose credentials or private data.\n- Provide practical evidence, not theory alone.\n- Do not pay for premium features to complete the task.","new_description":"[[AZ]]\nCompetitor Benchmark: Üç rəqibin açıq kanallarını araşdır. Mövqe və mesajları müqayisə et. Fərqləndirmə imkanını yaz. Pulsuz alətlər: Google Sheets. Nəticə: Competitor matrix.\n\n[[EN]]\nCompetitor Benchmark: Analyze three competitors' public channels. Compare positioning and messages. Identify a differentiation opportunity. Free tools: Google Sheets. Output: Competitor matrix."},{"slug":"talora-digital-marketing-2026","task_number":3,"title":"Value Proposition","old_instructions":"[[AZ]]\n## Məqsəd\nMəhsulun həll etdiyi ehtiyacı göstər ;  Üç mesaj variantı yaz ;  Auditoriyaya uyğun birini əsaslandır.\n\n## Addım-addım icra\n1. Məhsulun həll etdiyi ehtiyacı göstər.\n2. Üç mesaj variantı yaz.\n3. Auditoriyaya uyğun birini əsaslandır.\n4. Nəticəni yoxla, fərziyyələri və məlumat mənbələrini qeyd et.\n\n## Nə təhvil verilməlidir?\nMessaging framework. Fayl və ya oxuna bilən link, 3–5 cümləlik izah və istifadə edilən mənbələr.\n\n## Qəbul meyarları\nBütün üç addımın nəticəsi artefaktda görünür, verilən nümunələr təkrar yoxlana bilir, uydurma fakt və icazəsiz şəxsi məlumat yoxdur.\n\n[[EN]]\n## Goal\nDescribe the problem solved ;  Draft three message variations ;  Select one for the target audience.\n\n## Step-by-step\n1. Describe the problem solved.\n2. Draft three message variations.\n3. Select one for the target audience.\n4. Verify the result; document assumptions and sources.\n\n## Deliverables\nMessaging framework. Submit a readable file/link, a short explanation and credited sources.\n\n## Acceptance criteria\nEvidence supports all three steps, examples can be reviewed, and no fabricated facts or unauthorized personal data are included.","old_description":"[[AZ]]\nMəhsulun həll etdiyi ehtiyacı göstər ;  Üç mesaj variantı yaz ;  Auditoriyaya uyğun birini əsaslandır.\n\n[[EN]]\nDescribe the problem solved ;  Draft three message variations ;  Select one for the target audience.","new_instructions":"[[AZ]]\n## Tapşırığın məqsədi: Value Proposition\nBu tapşırıq birinci dəfə bu sahəni öyrənən tələbə üçün praktik işdir. Reklam büdcəsi tələb edilmir: məlumatı sintetik və ya mənbəli olaraq göstər.\n**Nümunə situasiya:** 'Tədbiri 3 dəqiqəyə tap' iddiasını yoxla; sübut yoxdursa yumşaq formada yaz.\n\n## Hansı pulsuz alətlər lazımdır?\n- **Google Docs** — https://docs.google.com/document/. Boş sənəd aç, başlıqları və cədvəlləri doldur, PDF kimi yüklə.\n> Heç bir pullu abunə, reklam büdcəsi və ya API açarı tələb olunmur. Free plan limiti bitdikdə lokal alternativdən istifadə et. Başqa şəxslərin şifrəsini, şəxsi məlumatını və icazəsiz fayllarını paylaşma.\n\n## Addım-addım icra təlimatı\n1. Öz iş qovluğunu yarat: Talora / Digital Marketing / Task-3. Əvvəlki tapşırıqların nəticəsi varsa onlardan istifadə et; yoxdursa 5 sintetik nümunə sətri hazırla.\n2. Bu tapşırığın məqsədini və istifadəçisini bir cümlədə yaz; nümunədə hansı nəticənin uğur sayılacağını müəyyən et.\n3. Məhsulun həll etdiyi ehtiyacı göstər. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n4. Üç mesaj variantı yaz. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n5. Auditoriyaya uyğun birini əsaslandır. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n6. Nümunəni işlə: 'Tədbiri 3 dəqiqəyə tap' iddiasını yoxla; sübut yoxdursa yumşaq formada yaz. Hansı məqamın düzgün işlədiyini və hansı məhdudiyyətin qaldığını ayrıca izah et.\n7. Əsas artefaktı hazırla: Messaging framework. Oxuna bilən PDF/fayl və ya paylaşılabilən linki yoxla; redaktə edilən orijinalı da saxla.\n8. Öz işini təkrar yoxla. Üç əsas addımı bitirdiyini göstər; 3–5 cümləlik nəticə, istifadə olunan alətlər və mənbələri qeyd et.\n\n## İşlənmiş nümunə necə görünməlidir?\n'Tədbiri 3 dəqiqəyə tap' iddiasını yoxla; sübut yoxdursa yumşaq formada yaz.\nBu nümunəni olduğu kimi kopyalama: öz sintetik ssenarinə uyğun doldur, araşdırdığın faktları və fərziyyələri ayır.\n\n## Nə təhvil verməlisən?\n- **Əsas nəticə:** Messaging framework.\n- **Sübut:** oxunan fayl və ya link; uyğun olduqda PDF, cədvəl, PNG, SVG, MP4, SRT, kod və ya layihə faylı.\n- **Qısa hesabat:** 3–5 cümlədə nə etdin, niyə bu üsulu seçdin, nəyi yoxladın?\n- **Mənbələr:** istinadlar, istifadə etdiyin vizual/audio materialın icazəsi.\n\n## Qiymətləndirmə meyarları (100 bal)\n- **40 bal:** Üç əsas fəaliyyətin hər biri real nəticədə görünür.\n- **25 bal:** Nümunə və məntiq yoxlanılıb, nəticə təkrarlana bilir.\n- **15 bal:** Fayl oxunaqlı, düzgün adlandırılıb və bölmələr aydındır.\n- **10 bal:** Məxfilik, müəlliflik və pulsuz istifadə qaydaları gözlənilib.\n- **10 bal:** Öz sözlərinlə yekun və mümkün təkmilləşdirmə izah olunub.\n\n## Göndərməzdən əvvəl yoxla\n- Demo nəticəni real kampaniya nəticəsi adlandırma.\n- Link başqa şəxsə oxu icazəsi verir, amma sənədin içində şəxsi məlumat və şifrə yoxdur.\n- Lazım olan hissələr sadəcə nəzəri cümlələr deyil, təqdim etdiyin real artefaktla sübut olunur.\n- Ödəniş qəbzi və ya Pro alət tələb olunmur.\n\n[[EN]]\n## Assignment goal: Value Proposition\nThis practical assignment is designed for beginners. No ad spend is necessary: use labeled synthetic or cited public data.\n**Example scenario:** Verify a 'find events in three minutes' claim or use qualified language.\n\n## Free tools and platforms\n- **Google Docs** — https://docs.google.com/document/. Create a blank document, organize headings/tables and export PDF.\n> No paid subscriptions, ad budgets or paid API keys are required. If a free quota is exhausted, choose a local alternative. Never share passwords, personal data or assets you cannot legally reuse.\n\n## Step-by-step guide\n1. Set up your work folder: Talora / Digital Marketing / Task-3. Reuse your earlier fictional artifacts or create five sample records.\n2. Explain the objective and intended user in one sentence; define what success would look like.\n3. Describe the problem solved. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n4. Draft three message variations. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n5. Select one for the target audience. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n6. Work through the scenario: Verify a 'find events in three minutes' claim or use qualified language. Document what worked and any limitations.\n7. Complete the main artifact: Messaging framework. Verify that a reader can open the PDF/file or shared link; keep the editable source too.\n8. Review all three essential actions, then write a three-to-five sentence conclusion listing tools, sources and improvements.\n\n## A worked example\nVerify a 'find events in three minutes' claim or use qualified language.\nDo not copy the example unchanged; adapt it to your own fictional scenario and distinguish evidence from assumptions.\n\n## What you must submit\n- **Primary artifact:** Messaging framework.\n- **Evidence:** a readable file/link or appropriate PDF, spreadsheet, PNG, SVG, MP4, SRT, source code or project file.\n- **Short report:** three to five sentences about your approach, what you verified and why.\n- **Sources:** citations and usage rights for images, audio or reused text.\n\n## Scoring rubric (100 points)\n- **40 points:** all three core actions are shown in the submitted work.\n- **25 points:** tested, accurate, reproducible result or example.\n- **15 points:** readable structure, proper filenames and export format.\n- **10 points:** privacy, licensing and free-tool rules followed.\n- **10 points:** your explanation and suggested improvements.\n\n## Final checklist\n- Never describe mock metrics as actual campaign results.\n- Test file permissions; never expose credentials or private data.\n- Provide practical evidence, not theory alone.\n- Do not pay for premium features to complete the task.","new_description":"[[AZ]]\nValue Proposition: Məhsulun həll etdiyi ehtiyacı göstər. Üç mesaj variantı yaz. Auditoriyaya uyğun birini əsaslandır. Pulsuz alətlər: Google Docs. Nəticə: Messaging framework.\n\n[[EN]]\nValue Proposition: Describe the problem solved. Draft three message variations. Select one for the target audience. Free tools: Google Docs. Output: Messaging framework."},{"slug":"talora-digital-marketing-2026","task_number":4,"title":"Channel Plan","old_instructions":"[[AZ]]\n## Məqsəd\nÜç marketinq kanalı seç ;  Hər biri üçün məqsəd və KPI yaz ;  Həftəlik kontent ritmi müəyyən et.\n\n## Addım-addım icra\n1. Üç marketinq kanalı seç.\n2. Hər biri üçün məqsəd və KPI yaz.\n3. Həftəlik kontent ritmi müəyyən et.\n4. Nəticəni yoxla, fərziyyələri və məlumat mənbələrini qeyd et.\n\n## Nə təhvil verilməlidir?\nChannel strategy. Fayl və ya oxuna bilən link, 3–5 cümləlik izah və istifadə edilən mənbələr.\n\n## Qəbul meyarları\nBütün üç addımın nəticəsi artefaktda görünür, verilən nümunələr təkrar yoxlana bilir, uydurma fakt və icazəsiz şəxsi məlumat yoxdur.\n\n[[EN]]\n## Goal\nChoose three channels ;  Assign goals and KPIs ;  Plan a weekly cadence.\n\n## Step-by-step\n1. Choose three channels.\n2. Assign goals and KPIs.\n3. Plan a weekly cadence.\n4. Verify the result; document assumptions and sources.\n\n## Deliverables\nChannel strategy. Submit a readable file/link, a short explanation and credited sources.\n\n## Acceptance criteria\nEvidence supports all three steps, examples can be reviewed, and no fabricated facts or unauthorized personal data are included.","old_description":"[[AZ]]\nÜç marketinq kanalı seç ;  Hər biri üçün məqsəd və KPI yaz ;  Həftəlik kontent ritmi müəyyən et.\n\n[[EN]]\nChoose three channels ;  Assign goals and KPIs ;  Plan a weekly cadence.","new_instructions":"[[AZ]]\n## Tapşırığın məqsədi: Channel Plan\nBu tapşırıq birinci dəfə bu sahəni öyrənən tələbə üçün praktik işdir. Reklam büdcəsi tələb edilmir: məlumatı sintetik və ya mənbəli olaraq göstər.\n**Nümunə situasiya:** Instagram reach, email signup və SEO discovery üçün ayrı məqsəd/KPI təyin et.\n\n## Hansı pulsuz alətlər lazımdır?\n- **Google Sheets** — https://sheets.google.com. Yeni cədvəl yarat, sütun adlarını və ən azı 5 sətirlik nümunəni daxil et.\n> Heç bir pullu abunə, reklam büdcəsi və ya API açarı tələb olunmur. Free plan limiti bitdikdə lokal alternativdən istifadə et. Başqa şəxslərin şifrəsini, şəxsi məlumatını və icazəsiz fayllarını paylaşma.\n\n## Addım-addım icra təlimatı\n1. Öz iş qovluğunu yarat: Talora / Digital Marketing / Task-4. Əvvəlki tapşırıqların nəticəsi varsa onlardan istifadə et; yoxdursa 5 sintetik nümunə sətri hazırla.\n2. Bu tapşırığın məqsədini və istifadəçisini bir cümlədə yaz; nümunədə hansı nəticənin uğur sayılacağını müəyyən et.\n3. Üç marketinq kanalı seç. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n4. Hər biri üçün məqsəd və KPI yaz. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n5. Həftəlik kontent ritmi müəyyən et. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n6. Nümunəni işlə: Instagram reach, email signup və SEO discovery üçün ayrı məqsəd/KPI təyin et. Hansı məqamın düzgün işlədiyini və hansı məhdudiyyətin qaldığını ayrıca izah et.\n7. Əsas artefaktı hazırla: Channel strategy. Oxuna bilən PDF/fayl və ya paylaşılabilən linki yoxla; redaktə edilən orijinalı da saxla.\n8. Öz işini təkrar yoxla. Üç əsas addımı bitirdiyini göstər; 3–5 cümləlik nəticə, istifadə olunan alətlər və mənbələri qeyd et.\n\n## İşlənmiş nümunə necə görünməlidir?\nInstagram reach, email signup və SEO discovery üçün ayrı məqsəd/KPI təyin et.\nBu nümunəni olduğu kimi kopyalama: öz sintetik ssenarinə uyğun doldur, araşdırdığın faktları və fərziyyələri ayır.\n\n## Nə təhvil verməlisən?\n- **Əsas nəticə:** Channel strategy.\n- **Sübut:** oxunan fayl və ya link; uyğun olduqda PDF, cədvəl, PNG, SVG, MP4, SRT, kod və ya layihə faylı.\n- **Qısa hesabat:** 3–5 cümlədə nə etdin, niyə bu üsulu seçdin, nəyi yoxladın?\n- **Mənbələr:** istinadlar, istifadə etdiyin vizual/audio materialın icazəsi.\n\n## Qiymətləndirmə meyarları (100 bal)\n- **40 bal:** Üç əsas fəaliyyətin hər biri real nəticədə görünür.\n- **25 bal:** Nümunə və məntiq yoxlanılıb, nəticə təkrarlana bilir.\n- **15 bal:** Fayl oxunaqlı, düzgün adlandırılıb və bölmələr aydındır.\n- **10 bal:** Məxfilik, müəlliflik və pulsuz istifadə qaydaları gözlənilib.\n- **10 bal:** Öz sözlərinlə yekun və mümkün təkmilləşdirmə izah olunub.\n\n## Göndərməzdən əvvəl yoxla\n- Demo nəticəni real kampaniya nəticəsi adlandırma.\n- Link başqa şəxsə oxu icazəsi verir, amma sənədin içində şəxsi məlumat və şifrə yoxdur.\n- Lazım olan hissələr sadəcə nəzəri cümlələr deyil, təqdim etdiyin real artefaktla sübut olunur.\n- Ödəniş qəbzi və ya Pro alət tələb olunmur.\n\n[[EN]]\n## Assignment goal: Channel Plan\nThis practical assignment is designed for beginners. No ad spend is necessary: use labeled synthetic or cited public data.\n**Example scenario:** Set distinct goals and metrics for social reach, email signups and SEO.\n\n## Free tools and platforms\n- **Google Sheets** — https://sheets.google.com. Create a sheet, name the columns and add at least five fictional rows.\n> No paid subscriptions, ad budgets or paid API keys are required. If a free quota is exhausted, choose a local alternative. Never share passwords, personal data or assets you cannot legally reuse.\n\n## Step-by-step guide\n1. Set up your work folder: Talora / Digital Marketing / Task-4. Reuse your earlier fictional artifacts or create five sample records.\n2. Explain the objective and intended user in one sentence; define what success would look like.\n3. Choose three channels. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n4. Assign goals and KPIs. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n5. Plan a weekly cadence. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n6. Work through the scenario: Set distinct goals and metrics for social reach, email signups and SEO. Document what worked and any limitations.\n7. Complete the main artifact: Channel strategy. Verify that a reader can open the PDF/file or shared link; keep the editable source too.\n8. Review all three essential actions, then write a three-to-five sentence conclusion listing tools, sources and improvements.\n\n## A worked example\nSet distinct goals and metrics for social reach, email signups and SEO.\nDo not copy the example unchanged; adapt it to your own fictional scenario and distinguish evidence from assumptions.\n\n## What you must submit\n- **Primary artifact:** Channel strategy.\n- **Evidence:** a readable file/link or appropriate PDF, spreadsheet, PNG, SVG, MP4, SRT, source code or project file.\n- **Short report:** three to five sentences about your approach, what you verified and why.\n- **Sources:** citations and usage rights for images, audio or reused text.\n\n## Scoring rubric (100 points)\n- **40 points:** all three core actions are shown in the submitted work.\n- **25 points:** tested, accurate, reproducible result or example.\n- **15 points:** readable structure, proper filenames and export format.\n- **10 points:** privacy, licensing and free-tool rules followed.\n- **10 points:** your explanation and suggested improvements.\n\n## Final checklist\n- Never describe mock metrics as actual campaign results.\n- Test file permissions; never expose credentials or private data.\n- Provide practical evidence, not theory alone.\n- Do not pay for premium features to complete the task.","new_description":"[[AZ]]\nChannel Plan: Üç marketinq kanalı seç. Hər biri üçün məqsəd və KPI yaz. Həftəlik kontent ritmi müəyyən et. Pulsuz alətlər: Google Sheets. Nəticə: Channel strategy.\n\n[[EN]]\nChannel Plan: Choose three channels. Assign goals and KPIs. Plan a weekly cadence. Free tools: Google Sheets. Output: Channel strategy."},{"slug":"talora-digital-marketing-2026","task_number":5,"title":"Keyword and Content Map","old_instructions":"[[AZ]]\n## Məqsəd\nOn SEO axtarış niyyəti müəyyən et ;  Mövzu klasteri yarat ;  İki məqalə planı yaz.\n\n## Addım-addım icra\n1. On SEO axtarış niyyəti müəyyən et.\n2. Mövzu klasteri yarat.\n3. İki məqalə planı yaz.\n4. Nəticəni yoxla, fərziyyələri və məlumat mənbələrini qeyd et.\n\n## Nə təhvil verilməlidir?\nSEO keyword map. Fayl və ya oxuna bilən link, 3–5 cümləlik izah və istifadə edilən mənbələr.\n\n## Qəbul meyarları\nBütün üç addımın nəticəsi artefaktda görünür, verilən nümunələr təkrar yoxlana bilir, uydurma fakt və icazəsiz şəxsi məlumat yoxdur.\n\n[[EN]]\n## Goal\nIdentify ten SEO search intents ;  Build topic clusters ;  Draft two article briefs.\n\n## Step-by-step\n1. Identify ten SEO search intents.\n2. Build topic clusters.\n3. Draft two article briefs.\n4. Verify the result; document assumptions and sources.\n\n## Deliverables\nSEO keyword map. Submit a readable file/link, a short explanation and credited sources.\n\n## Acceptance criteria\nEvidence supports all three steps, examples can be reviewed, and no fabricated facts or unauthorized personal data are included.","old_description":"[[AZ]]\nOn SEO axtarış niyyəti müəyyən et ;  Mövzu klasteri yarat ;  İki məqalə planı yaz.\n\n[[EN]]\nIdentify ten SEO search intents ;  Build topic clusters ;  Draft two article briefs.","new_instructions":"[[AZ]]\n## Tapşırığın məqsədi: Keyword and Content Map\nBu tapşırıq birinci dəfə bu sahəni öyrənən tələbə üçün praktik işdir. Reklam büdcəsi tələb edilmir: məlumatı sintetik və ya mənbəli olaraq göstər.\n**Nümunə situasiya:** 'Tələbə təcrübəsini necə tapmaq olar' tipli 10 axtarış niyyətini klasterləşdir.\n\n## Hansı pulsuz alətlər lazımdır?\n- **Google Trends** — https://trends.google.com. Axtarış ifadəsini yaz, bölgəni seç; indeks göstəricisini real axtarış sayı sayma.\n- **Google Sheets** — https://sheets.google.com. Yeni cədvəl yarat, sütun adlarını və ən azı 5 sətirlik nümunəni daxil et.\n> Heç bir pullu abunə, reklam büdcəsi və ya API açarı tələb olunmur. Free plan limiti bitdikdə lokal alternativdən istifadə et. Başqa şəxslərin şifrəsini, şəxsi məlumatını və icazəsiz fayllarını paylaşma.\n\n## Addım-addım icra təlimatı\n1. Öz iş qovluğunu yarat: Talora / Digital Marketing / Task-5. Əvvəlki tapşırıqların nəticəsi varsa onlardan istifadə et; yoxdursa 5 sintetik nümunə sətri hazırla.\n2. Bu tapşırığın məqsədini və istifadəçisini bir cümlədə yaz; nümunədə hansı nəticənin uğur sayılacağını müəyyən et.\n3. On SEO axtarış niyyəti müəyyən et. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n4. Mövzu klasteri yarat. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n5. İki məqalə planı yaz. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n6. Nümunəni işlə: 'Tələbə təcrübəsini necə tapmaq olar' tipli 10 axtarış niyyətini klasterləşdir. Hansı məqamın düzgün işlədiyini və hansı məhdudiyyətin qaldığını ayrıca izah et.\n7. Əsas artefaktı hazırla: SEO keyword map. Oxuna bilən PDF/fayl və ya paylaşılabilən linki yoxla; redaktə edilən orijinalı da saxla.\n8. Öz işini təkrar yoxla. Üç əsas addımı bitirdiyini göstər; 3–5 cümləlik nəticə, istifadə olunan alətlər və mənbələri qeyd et.\n\n## İşlənmiş nümunə necə görünməlidir?\n'Tələbə təcrübəsini necə tapmaq olar' tipli 10 axtarış niyyətini klasterləşdir.\nBu nümunəni olduğu kimi kopyalama: öz sintetik ssenarinə uyğun doldur, araşdırdığın faktları və fərziyyələri ayır.\n\n## Nə təhvil verməlisən?\n- **Əsas nəticə:** SEO keyword map.\n- **Sübut:** oxunan fayl və ya link; uyğun olduqda PDF, cədvəl, PNG, SVG, MP4, SRT, kod və ya layihə faylı.\n- **Qısa hesabat:** 3–5 cümlədə nə etdin, niyə bu üsulu seçdin, nəyi yoxladın?\n- **Mənbələr:** istinadlar, istifadə etdiyin vizual/audio materialın icazəsi.\n\n## Qiymətləndirmə meyarları (100 bal)\n- **40 bal:** Üç əsas fəaliyyətin hər biri real nəticədə görünür.\n- **25 bal:** Nümunə və məntiq yoxlanılıb, nəticə təkrarlana bilir.\n- **15 bal:** Fayl oxunaqlı, düzgün adlandırılıb və bölmələr aydındır.\n- **10 bal:** Məxfilik, müəlliflik və pulsuz istifadə qaydaları gözlənilib.\n- **10 bal:** Öz sözlərinlə yekun və mümkün təkmilləşdirmə izah olunub.\n\n## Göndərməzdən əvvəl yoxla\n- Demo nəticəni real kampaniya nəticəsi adlandırma.\n- Link başqa şəxsə oxu icazəsi verir, amma sənədin içində şəxsi məlumat və şifrə yoxdur.\n- Lazım olan hissələr sadəcə nəzəri cümlələr deyil, təqdim etdiyin real artefaktla sübut olunur.\n- Ödəniş qəbzi və ya Pro alət tələb olunmur.\n\n[[EN]]\n## Assignment goal: Keyword and Content Map\nThis practical assignment is designed for beginners. No ad spend is necessary: use labeled synthetic or cited public data.\n**Example scenario:** Cluster ten informational searches around finding internships.\n\n## Free tools and platforms\n- **Google Trends** — https://trends.google.com. Enter a query and region; the interest index is not absolute search volume.\n- **Google Sheets** — https://sheets.google.com. Create a sheet, name the columns and add at least five fictional rows.\n> No paid subscriptions, ad budgets or paid API keys are required. If a free quota is exhausted, choose a local alternative. Never share passwords, personal data or assets you cannot legally reuse.\n\n## Step-by-step guide\n1. Set up your work folder: Talora / Digital Marketing / Task-5. Reuse your earlier fictional artifacts or create five sample records.\n2. Explain the objective and intended user in one sentence; define what success would look like.\n3. Identify ten SEO search intents. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n4. Build topic clusters. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n5. Draft two article briefs. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n6. Work through the scenario: Cluster ten informational searches around finding internships. Document what worked and any limitations.\n7. Complete the main artifact: SEO keyword map. Verify that a reader can open the PDF/file or shared link; keep the editable source too.\n8. Review all three essential actions, then write a three-to-five sentence conclusion listing tools, sources and improvements.\n\n## A worked example\nCluster ten informational searches around finding internships.\nDo not copy the example unchanged; adapt it to your own fictional scenario and distinguish evidence from assumptions.\n\n## What you must submit\n- **Primary artifact:** SEO keyword map.\n- **Evidence:** a readable file/link or appropriate PDF, spreadsheet, PNG, SVG, MP4, SRT, source code or project file.\n- **Short report:** three to five sentences about your approach, what you verified and why.\n- **Sources:** citations and usage rights for images, audio or reused text.\n\n## Scoring rubric (100 points)\n- **40 points:** all three core actions are shown in the submitted work.\n- **25 points:** tested, accurate, reproducible result or example.\n- **15 points:** readable structure, proper filenames and export format.\n- **10 points:** privacy, licensing and free-tool rules followed.\n- **10 points:** your explanation and suggested improvements.\n\n## Final checklist\n- Never describe mock metrics as actual campaign results.\n- Test file permissions; never expose credentials or private data.\n- Provide practical evidence, not theory alone.\n- Do not pay for premium features to complete the task.","new_description":"[[AZ]]\nKeyword and Content Map: On SEO axtarış niyyəti müəyyən et. Mövzu klasteri yarat. İki məqalə planı yaz. Pulsuz alətlər: Google Trends, Google Sheets. Nəticə: SEO keyword map.\n\n[[EN]]\nKeyword and Content Map: Identify ten SEO search intents. Build topic clusters. Draft two article briefs. Free tools: Google Trends, Google Sheets. Output: SEO keyword map."},{"slug":"talora-digital-marketing-2026","task_number":6,"title":"Landing Page Copy","old_instructions":"[[AZ]]\n## Məqsəd\nHero, fayda və CTA mətni yaz ;  Mobil oxunaqlığı yoxla ;  Yanıltıcı iddiaları aradan qaldır.\n\n## Addım-addım icra\n1. Hero, fayda və CTA mətni yaz.\n2. Mobil oxunaqlığı yoxla.\n3. Yanıltıcı iddiaları aradan qaldır.\n4. Nəticəni yoxla, fərziyyələri və məlumat mənbələrini qeyd et.\n\n## Nə təhvil verilməlidir?\nLanding page wire copy. Fayl və ya oxuna bilən link, 3–5 cümləlik izah və istifadə edilən mənbələr.\n\n## Qəbul meyarları\nBütün üç addımın nəticəsi artefaktda görünür, verilən nümunələr təkrar yoxlana bilir, uydurma fakt və icazəsiz şəxsi məlumat yoxdur.\n\n[[EN]]\n## Goal\nWrite hero, benefits and CTA copy ;  Check mobile readability ;  Remove unsupported claims.\n\n## Step-by-step\n1. Write hero, benefits and CTA copy.\n2. Check mobile readability.\n3. Remove unsupported claims.\n4. Verify the result; document assumptions and sources.\n\n## Deliverables\nLanding page copy. Submit a readable file/link, a short explanation and credited sources.\n\n## Acceptance criteria\nEvidence supports all three steps, examples can be reviewed, and no fabricated facts or unauthorized personal data are included.","old_description":"[[AZ]]\nHero, fayda və CTA mətni yaz ;  Mobil oxunaqlığı yoxla ;  Yanıltıcı iddiaları aradan qaldır.\n\n[[EN]]\nWrite hero, benefits and CTA copy ;  Check mobile readability ;  Remove unsupported claims.","new_instructions":"[[AZ]]\n## Tapşırığın məqsədi: Landing Page Copy\nBu tapşırıq birinci dəfə bu sahəni öyrənən tələbə üçün praktik işdir. Reklam büdcəsi tələb edilmir: məlumatı sintetik və ya mənbəli olaraq göstər.\n**Nümunə situasiya:** Hero, 3 fayda, CTA və FAQ ilə bir səhifəlik landing copy hazırla.\n\n## Hansı pulsuz alətlər lazımdır?\n- **Google Docs** — https://docs.google.com/document/. Boş sənəd aç, başlıqları və cədvəlləri doldur, PDF kimi yüklə.\n- **Canva Free** — https://www.canva.com. Yalnız Free elementlərdən istifadə et, nəticəni PNG/PDF ixrac et; Pro elementə pul vermə.\n> Heç bir pullu abunə, reklam büdcəsi və ya API açarı tələb olunmur. Free plan limiti bitdikdə lokal alternativdən istifadə et. Başqa şəxslərin şifrəsini, şəxsi məlumatını və icazəsiz fayllarını paylaşma.\n\n## Addım-addım icra təlimatı\n1. Öz iş qovluğunu yarat: Talora / Digital Marketing / Task-6. Əvvəlki tapşırıqların nəticəsi varsa onlardan istifadə et; yoxdursa 5 sintetik nümunə sətri hazırla.\n2. Bu tapşırığın məqsədini və istifadəçisini bir cümlədə yaz; nümunədə hansı nəticənin uğur sayılacağını müəyyən et.\n3. Hero, fayda və CTA mətni yaz. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n4. Mobil oxunaqlığı yoxla. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n5. Yanıltıcı iddiaları aradan qaldır. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n6. Nümunəni işlə: Hero, 3 fayda, CTA və FAQ ilə bir səhifəlik landing copy hazırla. Hansı məqamın düzgün işlədiyini və hansı məhdudiyyətin qaldığını ayrıca izah et.\n7. Əsas artefaktı hazırla: Landing page wire copy. Oxuna bilən PDF/fayl və ya paylaşılabilən linki yoxla; redaktə edilən orijinalı da saxla.\n8. Öz işini təkrar yoxla. Üç əsas addımı bitirdiyini göstər; 3–5 cümləlik nəticə, istifadə olunan alətlər və mənbələri qeyd et.\n\n## İşlənmiş nümunə necə görünməlidir?\nHero, 3 fayda, CTA və FAQ ilə bir səhifəlik landing copy hazırla.\nBu nümunəni olduğu kimi kopyalama: öz sintetik ssenarinə uyğun doldur, araşdırdığın faktları və fərziyyələri ayır.\n\n## Nə təhvil verməlisən?\n- **Əsas nəticə:** Landing page wire copy.\n- **Sübut:** oxunan fayl və ya link; uyğun olduqda PDF, cədvəl, PNG, SVG, MP4, SRT, kod və ya layihə faylı.\n- **Qısa hesabat:** 3–5 cümlədə nə etdin, niyə bu üsulu seçdin, nəyi yoxladın?\n- **Mənbələr:** istinadlar, istifadə etdiyin vizual/audio materialın icazəsi.\n\n## Qiymətləndirmə meyarları (100 bal)\n- **40 bal:** Üç əsas fəaliyyətin hər biri real nəticədə görünür.\n- **25 bal:** Nümunə və məntiq yoxlanılıb, nəticə təkrarlana bilir.\n- **15 bal:** Fayl oxunaqlı, düzgün adlandırılıb və bölmələr aydındır.\n- **10 bal:** Məxfilik, müəlliflik və pulsuz istifadə qaydaları gözlənilib.\n- **10 bal:** Öz sözlərinlə yekun və mümkün təkmilləşdirmə izah olunub.\n\n## Göndərməzdən əvvəl yoxla\n- Demo nəticəni real kampaniya nəticəsi adlandırma.\n- Link başqa şəxsə oxu icazəsi verir, amma sənədin içində şəxsi məlumat və şifrə yoxdur.\n- Lazım olan hissələr sadəcə nəzəri cümlələr deyil, təqdim etdiyin real artefaktla sübut olunur.\n- Ödəniş qəbzi və ya Pro alət tələb olunmur.\n\n[[EN]]\n## Assignment goal: Landing Page Copy\nThis practical assignment is designed for beginners. No ad spend is necessary: use labeled synthetic or cited public data.\n**Example scenario:** Write landing page copy with a hero, three benefits, a CTA and an FAQ.\n\n## Free tools and platforms\n- **Google Docs** — https://docs.google.com/document/. Create a blank document, organize headings/tables and export PDF.\n- **Canva Free** — https://www.canva.com. Use only Free elements, export PNG/PDF and avoid Pro assets.\n> No paid subscriptions, ad budgets or paid API keys are required. If a free quota is exhausted, choose a local alternative. Never share passwords, personal data or assets you cannot legally reuse.\n\n## Step-by-step guide\n1. Set up your work folder: Talora / Digital Marketing / Task-6. Reuse your earlier fictional artifacts or create five sample records.\n2. Explain the objective and intended user in one sentence; define what success would look like.\n3. Write hero, benefits and CTA copy. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n4. Check mobile readability. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n5. Remove unsupported claims. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n6. Work through the scenario: Write landing page copy with a hero, three benefits, a CTA and an FAQ. Document what worked and any limitations.\n7. Complete the main artifact: Landing page copy. Verify that a reader can open the PDF/file or shared link; keep the editable source too.\n8. Review all three essential actions, then write a three-to-five sentence conclusion listing tools, sources and improvements.\n\n## A worked example\nWrite landing page copy with a hero, three benefits, a CTA and an FAQ.\nDo not copy the example unchanged; adapt it to your own fictional scenario and distinguish evidence from assumptions.\n\n## What you must submit\n- **Primary artifact:** Landing page copy.\n- **Evidence:** a readable file/link or appropriate PDF, spreadsheet, PNG, SVG, MP4, SRT, source code or project file.\n- **Short report:** three to five sentences about your approach, what you verified and why.\n- **Sources:** citations and usage rights for images, audio or reused text.\n\n## Scoring rubric (100 points)\n- **40 points:** all three core actions are shown in the submitted work.\n- **25 points:** tested, accurate, reproducible result or example.\n- **15 points:** readable structure, proper filenames and export format.\n- **10 points:** privacy, licensing and free-tool rules followed.\n- **10 points:** your explanation and suggested improvements.\n\n## Final checklist\n- Never describe mock metrics as actual campaign results.\n- Test file permissions; never expose credentials or private data.\n- Provide practical evidence, not theory alone.\n- Do not pay for premium features to complete the task.","new_description":"[[AZ]]\nLanding Page Copy: Hero, fayda və CTA mətni yaz. Mobil oxunaqlığı yoxla. Yanıltıcı iddiaları aradan qaldır. Pulsuz alətlər: Google Docs, Canva Free. Nəticə: Landing page wire copy.\n\n[[EN]]\nLanding Page Copy: Write hero, benefits and CTA copy. Check mobile readability. Remove unsupported claims. Free tools: Google Docs, Canva Free. Output: Landing page copy."},{"slug":"talora-digital-marketing-2026","task_number":7,"title":"Email Lifecycle Design","old_instructions":"[[AZ]]\n## Məqsəd\nİcazəli abunə ssenarisi qur ;  Üç e-poçt mesajı yaz ;  Opt-out və məxfilik qeydini daxil et.\n\n## Addım-addım icra\n1. İcazəli abunə ssenarisi qur.\n2. Üç e-poçt mesajı yaz.\n3. Opt-out və məxfilik qeydini daxil et.\n4. Nəticəni yoxla, fərziyyələri və məlumat mənbələrini qeyd et.\n\n## Nə təhvil verilməlidir?\nEmail sequence. Fayl və ya oxuna bilən link, 3–5 cümləlik izah və istifadə edilən mənbələr.\n\n## Qəbul meyarları\nBütün üç addımın nəticəsi artefaktda görünür, verilən nümunələr təkrar yoxlana bilir, uydurma fakt və icazəsiz şəxsi məlumat yoxdur.\n\n[[EN]]\n## Goal\nDesign a consent-based subscriber journey ;  Draft three emails ;  Add unsubscribe and privacy handling.\n\n## Step-by-step\n1. Design a consent-based subscriber journey.\n2. Draft three emails.\n3. Add unsubscribe and privacy handling.\n4. Verify the result; document assumptions and sources.\n\n## Deliverables\nEmail sequence. Submit a readable file/link, a short explanation and credited sources.\n\n## Acceptance criteria\nEvidence supports all three steps, examples can be reviewed, and no fabricated facts or unauthorized personal data are included.","old_description":"[[AZ]]\nİcazəli abunə ssenarisi qur ;  Üç e-poçt mesajı yaz ;  Opt-out və məxfilik qeydini daxil et.\n\n[[EN]]\nDesign a consent-based subscriber journey ;  Draft three emails ;  Add unsubscribe and privacy handling.","new_instructions":"[[AZ]]\n## Tapşırığın məqsədi: Email Lifecycle Design\nBu tapşırıq birinci dəfə bu sahəni öyrənən tələbə üçün praktik işdir. Reklam büdcəsi tələb edilmir: məlumatı sintetik və ya mənbəli olaraq göstər.\n**Nümunə situasiya:** Razılığa əsaslanan 3 email: xoş gəldin, xatırlatma, yekun; real ünvanlara göndərmə.\n\n## Hansı pulsuz alətlər lazımdır?\n- **Google Docs** — https://docs.google.com/document/. Boş sənəd aç, başlıqları və cədvəlləri doldur, PDF kimi yüklə.\n> Heç bir pullu abunə, reklam büdcəsi və ya API açarı tələb olunmur. Free plan limiti bitdikdə lokal alternativdən istifadə et. Başqa şəxslərin şifrəsini, şəxsi məlumatını və icazəsiz fayllarını paylaşma.\n\n## Addım-addım icra təlimatı\n1. Öz iş qovluğunu yarat: Talora / Digital Marketing / Task-7. Əvvəlki tapşırıqların nəticəsi varsa onlardan istifadə et; yoxdursa 5 sintetik nümunə sətri hazırla.\n2. Bu tapşırığın məqsədini və istifadəçisini bir cümlədə yaz; nümunədə hansı nəticənin uğur sayılacağını müəyyən et.\n3. İcazəli abunə ssenarisi qur. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n4. Üç e-poçt mesajı yaz. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n5. Opt-out və məxfilik qeydini daxil et. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n6. Nümunəni işlə: Razılığa əsaslanan 3 email: xoş gəldin, xatırlatma, yekun; real ünvanlara göndərmə. Hansı məqamın düzgün işlədiyini və hansı məhdudiyyətin qaldığını ayrıca izah et.\n7. Əsas artefaktı hazırla: Email sequence. Oxuna bilən PDF/fayl və ya paylaşılabilən linki yoxla; redaktə edilən orijinalı da saxla.\n8. Öz işini təkrar yoxla. Üç əsas addımı bitirdiyini göstər; 3–5 cümləlik nəticə, istifadə olunan alətlər və mənbələri qeyd et.\n\n## İşlənmiş nümunə necə görünməlidir?\nRazılığa əsaslanan 3 email: xoş gəldin, xatırlatma, yekun; real ünvanlara göndərmə.\nBu nümunəni olduğu kimi kopyalama: öz sintetik ssenarinə uyğun doldur, araşdırdığın faktları və fərziyyələri ayır.\n\n## Nə təhvil verməlisən?\n- **Əsas nəticə:** Email sequence.\n- **Sübut:** oxunan fayl və ya link; uyğun olduqda PDF, cədvəl, PNG, SVG, MP4, SRT, kod və ya layihə faylı.\n- **Qısa hesabat:** 3–5 cümlədə nə etdin, niyə bu üsulu seçdin, nəyi yoxladın?\n- **Mənbələr:** istinadlar, istifadə etdiyin vizual/audio materialın icazəsi.\n\n## Qiymətləndirmə meyarları (100 bal)\n- **40 bal:** Üç əsas fəaliyyətin hər biri real nəticədə görünür.\n- **25 bal:** Nümunə və məntiq yoxlanılıb, nəticə təkrarlana bilir.\n- **15 bal:** Fayl oxunaqlı, düzgün adlandırılıb və bölmələr aydındır.\n- **10 bal:** Məxfilik, müəlliflik və pulsuz istifadə qaydaları gözlənilib.\n- **10 bal:** Öz sözlərinlə yekun və mümkün təkmilləşdirmə izah olunub.\n\n## Göndərməzdən əvvəl yoxla\n- Demo nəticəni real kampaniya nəticəsi adlandırma.\n- Link başqa şəxsə oxu icazəsi verir, amma sənədin içində şəxsi məlumat və şifrə yoxdur.\n- Lazım olan hissələr sadəcə nəzəri cümlələr deyil, təqdim etdiyin real artefaktla sübut olunur.\n- Ödəniş qəbzi və ya Pro alət tələb olunmur.\n\n[[EN]]\n## Assignment goal: Email Lifecycle Design\nThis practical assignment is designed for beginners. No ad spend is necessary: use labeled synthetic or cited public data.\n**Example scenario:** Write a consent-based welcome, reminder and follow-up sequence without mailing anyone.\n\n## Free tools and platforms\n- **Google Docs** — https://docs.google.com/document/. Create a blank document, organize headings/tables and export PDF.\n> No paid subscriptions, ad budgets or paid API keys are required. If a free quota is exhausted, choose a local alternative. Never share passwords, personal data or assets you cannot legally reuse.\n\n## Step-by-step guide\n1. Set up your work folder: Talora / Digital Marketing / Task-7. Reuse your earlier fictional artifacts or create five sample records.\n2. Explain the objective and intended user in one sentence; define what success would look like.\n3. Design a consent-based subscriber journey. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n4. Draft three emails. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n5. Add unsubscribe and privacy handling. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n6. Work through the scenario: Write a consent-based welcome, reminder and follow-up sequence without mailing anyone. Document what worked and any limitations.\n7. Complete the main artifact: Email sequence. Verify that a reader can open the PDF/file or shared link; keep the editable source too.\n8. Review all three essential actions, then write a three-to-five sentence conclusion listing tools, sources and improvements.\n\n## A worked example\nWrite a consent-based welcome, reminder and follow-up sequence without mailing anyone.\nDo not copy the example unchanged; adapt it to your own fictional scenario and distinguish evidence from assumptions.\n\n## What you must submit\n- **Primary artifact:** Email sequence.\n- **Evidence:** a readable file/link or appropriate PDF, spreadsheet, PNG, SVG, MP4, SRT, source code or project file.\n- **Short report:** three to five sentences about your approach, what you verified and why.\n- **Sources:** citations and usage rights for images, audio or reused text.\n\n## Scoring rubric (100 points)\n- **40 points:** all three core actions are shown in the submitted work.\n- **25 points:** tested, accurate, reproducible result or example.\n- **15 points:** readable structure, proper filenames and export format.\n- **10 points:** privacy, licensing and free-tool rules followed.\n- **10 points:** your explanation and suggested improvements.\n\n## Final checklist\n- Never describe mock metrics as actual campaign results.\n- Test file permissions; never expose credentials or private data.\n- Provide practical evidence, not theory alone.\n- Do not pay for premium features to complete the task.","new_description":"[[AZ]]\nEmail Lifecycle Design: İcazəli abunə ssenarisi qur. Üç e-poçt mesajı yaz. Opt-out və məxfilik qeydini daxil et. Pulsuz alətlər: Google Docs. Nəticə: Email sequence.\n\n[[EN]]\nEmail Lifecycle Design: Design a consent-based subscriber journey. Draft three emails. Add unsubscribe and privacy handling. Free tools: Google Docs. Output: Email sequence."},{"slug":"talora-digital-marketing-2026","task_number":8,"title":"A/B Test Proposal","old_instructions":"[[AZ]]\n## Məqsəd\nBir dəyişəni seç ;  Hipotez, metric və stop qaydasını yaz ;  Sintetik datasetlə nümunə nəticə hesabla.\n\n## Addım-addım icra\n1. Bir dəyişəni seç.\n2. Hipotez, metric və stop qaydasını yaz.\n3. Sintetik datasetlə nümunə nəticə hesabla.\n4. Nəticəni yoxla, fərziyyələri və məlumat mənbələrini qeyd et.\n\n## Nə təhvil verilməlidir?\nExperiment plan. Fayl və ya oxuna bilən link, 3–5 cümləlik izah və istifadə edilən mənbələr.\n\n## Qəbul meyarları\nBütün üç addımın nəticəsi artefaktda görünür, verilən nümunələr təkrar yoxlana bilir, uydurma fakt və icazəsiz şəxsi məlumat yoxdur.\n\n[[EN]]\n## Goal\nChoose one variable ;  Specify hypothesis, metric and stop rule ;  Evaluate with synthetic data.\n\n## Step-by-step\n1. Choose one variable.\n2. Specify hypothesis, metric and stop rule.\n3. Evaluate with synthetic data.\n4. Verify the result; document assumptions and sources.\n\n## Deliverables\nExperiment plan. Submit a readable file/link, a short explanation and credited sources.\n\n## Acceptance criteria\nEvidence supports all three steps, examples can be reviewed, and no fabricated facts or unauthorized personal data are included.","old_description":"[[AZ]]\nBir dəyişəni seç ;  Hipotez, metric və stop qaydasını yaz ;  Sintetik datasetlə nümunə nəticə hesabla.\n\n[[EN]]\nChoose one variable ;  Specify hypothesis, metric and stop rule ;  Evaluate with synthetic data.","new_instructions":"[[AZ]]\n## Tapşırığın məqsədi: A/B Test Proposal\nBu tapşırıq birinci dəfə bu sahəni öyrənən tələbə üçün praktik işdir. Reklam büdcəsi tələb edilmir: məlumatı sintetik və ya mənbəli olaraq göstər.\n**Nümunə situasiya:** İki CTA-nı 1000 sintetik baxışla müqayisə et; nəticənin məhdudluğunu yaz.\n\n## Hansı pulsuz alətlər lazımdır?\n- **Google Sheets** — https://sheets.google.com. Yeni cədvəl yarat, sütun adlarını və ən azı 5 sətirlik nümunəni daxil et.\n> Heç bir pullu abunə, reklam büdcəsi və ya API açarı tələb olunmur. Free plan limiti bitdikdə lokal alternativdən istifadə et. Başqa şəxslərin şifrəsini, şəxsi məlumatını və icazəsiz fayllarını paylaşma.\n\n## Addım-addım icra təlimatı\n1. Öz iş qovluğunu yarat: Talora / Digital Marketing / Task-8. Əvvəlki tapşırıqların nəticəsi varsa onlardan istifadə et; yoxdursa 5 sintetik nümunə sətri hazırla.\n2. Bu tapşırığın məqsədini və istifadəçisini bir cümlədə yaz; nümunədə hansı nəticənin uğur sayılacağını müəyyən et.\n3. Bir dəyişəni seç. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n4. Hipotez, metric və stop qaydasını yaz. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n5. Sintetik datasetlə nümunə nəticə hesabla. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n6. Nümunəni işlə: İki CTA-nı 1000 sintetik baxışla müqayisə et; nəticənin məhdudluğunu yaz. Hansı məqamın düzgün işlədiyini və hansı məhdudiyyətin qaldığını ayrıca izah et.\n7. Əsas artefaktı hazırla: Experiment plan. Oxuna bilən PDF/fayl və ya paylaşılabilən linki yoxla; redaktə edilən orijinalı da saxla.\n8. Öz işini təkrar yoxla. Üç əsas addımı bitirdiyini göstər; 3–5 cümləlik nəticə, istifadə olunan alətlər və mənbələri qeyd et.\n\n## İşlənmiş nümunə necə görünməlidir?\nİki CTA-nı 1000 sintetik baxışla müqayisə et; nəticənin məhdudluğunu yaz.\nBu nümunəni olduğu kimi kopyalama: öz sintetik ssenarinə uyğun doldur, araşdırdığın faktları və fərziyyələri ayır.\n\n## Nə təhvil verməlisən?\n- **Əsas nəticə:** Experiment plan.\n- **Sübut:** oxunan fayl və ya link; uyğun olduqda PDF, cədvəl, PNG, SVG, MP4, SRT, kod və ya layihə faylı.\n- **Qısa hesabat:** 3–5 cümlədə nə etdin, niyə bu üsulu seçdin, nəyi yoxladın?\n- **Mənbələr:** istinadlar, istifadə etdiyin vizual/audio materialın icazəsi.\n\n## Qiymətləndirmə meyarları (100 bal)\n- **40 bal:** Üç əsas fəaliyyətin hər biri real nəticədə görünür.\n- **25 bal:** Nümunə və məntiq yoxlanılıb, nəticə təkrarlana bilir.\n- **15 bal:** Fayl oxunaqlı, düzgün adlandırılıb və bölmələr aydındır.\n- **10 bal:** Məxfilik, müəlliflik və pulsuz istifadə qaydaları gözlənilib.\n- **10 bal:** Öz sözlərinlə yekun və mümkün təkmilləşdirmə izah olunub.\n\n## Göndərməzdən əvvəl yoxla\n- Demo nəticəni real kampaniya nəticəsi adlandırma.\n- Link başqa şəxsə oxu icazəsi verir, amma sənədin içində şəxsi məlumat və şifrə yoxdur.\n- Lazım olan hissələr sadəcə nəzəri cümlələr deyil, təqdim etdiyin real artefaktla sübut olunur.\n- Ödəniş qəbzi və ya Pro alət tələb olunmur.\n\n[[EN]]\n## Assignment goal: A/B Test Proposal\nThis practical assignment is designed for beginners. No ad spend is necessary: use labeled synthetic or cited public data.\n**Example scenario:** Compare two CTAs using a fictional 1,000-visit sample and discuss uncertainty.\n\n## Free tools and platforms\n- **Google Sheets** — https://sheets.google.com. Create a sheet, name the columns and add at least five fictional rows.\n> No paid subscriptions, ad budgets or paid API keys are required. If a free quota is exhausted, choose a local alternative. Never share passwords, personal data or assets you cannot legally reuse.\n\n## Step-by-step guide\n1. Set up your work folder: Talora / Digital Marketing / Task-8. Reuse your earlier fictional artifacts or create five sample records.\n2. Explain the objective and intended user in one sentence; define what success would look like.\n3. Choose one variable. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n4. Specify hypothesis, metric and stop rule. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n5. Evaluate with synthetic data. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n6. Work through the scenario: Compare two CTAs using a fictional 1,000-visit sample and discuss uncertainty. Document what worked and any limitations.\n7. Complete the main artifact: Experiment plan. Verify that a reader can open the PDF/file or shared link; keep the editable source too.\n8. Review all three essential actions, then write a three-to-five sentence conclusion listing tools, sources and improvements.\n\n## A worked example\nCompare two CTAs using a fictional 1,000-visit sample and discuss uncertainty.\nDo not copy the example unchanged; adapt it to your own fictional scenario and distinguish evidence from assumptions.\n\n## What you must submit\n- **Primary artifact:** Experiment plan.\n- **Evidence:** a readable file/link or appropriate PDF, spreadsheet, PNG, SVG, MP4, SRT, source code or project file.\n- **Short report:** three to five sentences about your approach, what you verified and why.\n- **Sources:** citations and usage rights for images, audio or reused text.\n\n## Scoring rubric (100 points)\n- **40 points:** all three core actions are shown in the submitted work.\n- **25 points:** tested, accurate, reproducible result or example.\n- **15 points:** readable structure, proper filenames and export format.\n- **10 points:** privacy, licensing and free-tool rules followed.\n- **10 points:** your explanation and suggested improvements.\n\n## Final checklist\n- Never describe mock metrics as actual campaign results.\n- Test file permissions; never expose credentials or private data.\n- Provide practical evidence, not theory alone.\n- Do not pay for premium features to complete the task.","new_description":"[[AZ]]\nA/B Test Proposal: Bir dəyişəni seç. Hipotez, metric və stop qaydasını yaz. Sintetik datasetlə nümunə nəticə hesabla. Pulsuz alətlər: Google Sheets. Nəticə: Experiment plan.\n\n[[EN]]\nA/B Test Proposal: Choose one variable. Specify hypothesis, metric and stop rule. Evaluate with synthetic data. Free tools: Google Sheets. Output: Experiment plan."},{"slug":"talora-digital-marketing-2026","task_number":9,"title":"Campaign Dashboard","old_instructions":"[[AZ]]\n## Məqsəd\nCTR, conversion və cost göstəricilərini müəyyən et ;  Sintetik nəticələri dashboard-da göstər ;  Məhdudiyyətləri qeyd et.\n\n## Addım-addım icra\n1. CTR, conversion və cost göstəricilərini müəyyən et.\n2. Sintetik nəticələri dashboard-da göstər.\n3. Məhdudiyyətləri qeyd et.\n4. Nəticəni yoxla, fərziyyələri və məlumat mənbələrini qeyd et.\n\n## Nə təhvil verilməlidir?\nCampaign metrics dashboard. Fayl və ya oxuna bilən link, 3–5 cümləlik izah və istifadə edilən mənbələr.\n\n## Qəbul meyarları\nBütün üç addımın nəticəsi artefaktda görünür, verilən nümunələr təkrar yoxlana bilir, uydurma fakt və icazəsiz şəxsi məlumat yoxdur.\n\n[[EN]]\n## Goal\nDefine CTR, conversion and cost metrics ;  Visualize synthetic results ;  Document limitations.\n\n## Step-by-step\n1. Define CTR, conversion and cost metrics.\n2. Visualize synthetic results.\n3. Document limitations.\n4. Verify the result; document assumptions and sources.\n\n## Deliverables\nCampaign dashboard. Submit a readable file/link, a short explanation and credited sources.\n\n## Acceptance criteria\nEvidence supports all three steps, examples can be reviewed, and no fabricated facts or unauthorized personal data are included.","old_description":"[[AZ]]\nCTR, conversion və cost göstəricilərini müəyyən et ;  Sintetik nəticələri dashboard-da göstər ;  Məhdudiyyətləri qeyd et.\n\n[[EN]]\nDefine CTR, conversion and cost metrics ;  Visualize synthetic results ;  Document limitations.","new_instructions":"[[AZ]]\n## Tapşırığın məqsədi: Campaign Dashboard\nBu tapşırıq birinci dəfə bu sahəni öyrənən tələbə üçün praktik işdir. Reklam büdcəsi tələb edilmir: məlumatı sintetik və ya mənbəli olaraq göstər.\n**Nümunə situasiya:** CTR və conversion düsturlarını 5 sətrlik sintetik data ilə hesabla.\n\n## Hansı pulsuz alətlər lazımdır?\n- **Google Sheets** — https://sheets.google.com. Yeni cədvəl yarat, sütun adlarını və ən azı 5 sətirlik nümunəni daxil et.\n> Heç bir pullu abunə, reklam büdcəsi və ya API açarı tələb olunmur. Free plan limiti bitdikdə lokal alternativdən istifadə et. Başqa şəxslərin şifrəsini, şəxsi məlumatını və icazəsiz fayllarını paylaşma.\n\n## Addım-addım icra təlimatı\n1. Öz iş qovluğunu yarat: Talora / Digital Marketing / Task-9. Əvvəlki tapşırıqların nəticəsi varsa onlardan istifadə et; yoxdursa 5 sintetik nümunə sətri hazırla.\n2. Bu tapşırığın məqsədini və istifadəçisini bir cümlədə yaz; nümunədə hansı nəticənin uğur sayılacağını müəyyən et.\n3. CTR, conversion və cost göstəricilərini müəyyən et. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n4. Sintetik nəticələri dashboard-da göstər. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n5. Məhdudiyyətləri qeyd et. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n6. Nümunəni işlə: CTR və conversion düsturlarını 5 sətrlik sintetik data ilə hesabla. Hansı məqamın düzgün işlədiyini və hansı məhdudiyyətin qaldığını ayrıca izah et.\n7. Əsas artefaktı hazırla: Campaign metrics dashboard. Oxuna bilən PDF/fayl və ya paylaşılabilən linki yoxla; redaktə edilən orijinalı da saxla.\n8. Öz işini təkrar yoxla. Üç əsas addımı bitirdiyini göstər; 3–5 cümləlik nəticə, istifadə olunan alətlər və mənbələri qeyd et.\n\n## İşlənmiş nümunə necə görünməlidir?\nCTR və conversion düsturlarını 5 sətrlik sintetik data ilə hesabla.\nBu nümunəni olduğu kimi kopyalama: öz sintetik ssenarinə uyğun doldur, araşdırdığın faktları və fərziyyələri ayır.\n\n## Nə təhvil verməlisən?\n- **Əsas nəticə:** Campaign metrics dashboard.\n- **Sübut:** oxunan fayl və ya link; uyğun olduqda PDF, cədvəl, PNG, SVG, MP4, SRT, kod və ya layihə faylı.\n- **Qısa hesabat:** 3–5 cümlədə nə etdin, niyə bu üsulu seçdin, nəyi yoxladın?\n- **Mənbələr:** istinadlar, istifadə etdiyin vizual/audio materialın icazəsi.\n\n## Qiymətləndirmə meyarları (100 bal)\n- **40 bal:** Üç əsas fəaliyyətin hər biri real nəticədə görünür.\n- **25 bal:** Nümunə və məntiq yoxlanılıb, nəticə təkrarlana bilir.\n- **15 bal:** Fayl oxunaqlı, düzgün adlandırılıb və bölmələr aydındır.\n- **10 bal:** Məxfilik, müəlliflik və pulsuz istifadə qaydaları gözlənilib.\n- **10 bal:** Öz sözlərinlə yekun və mümkün təkmilləşdirmə izah olunub.\n\n## Göndərməzdən əvvəl yoxla\n- Demo nəticəni real kampaniya nəticəsi adlandırma.\n- Link başqa şəxsə oxu icazəsi verir, amma sənədin içində şəxsi məlumat və şifrə yoxdur.\n- Lazım olan hissələr sadəcə nəzəri cümlələr deyil, təqdim etdiyin real artefaktla sübut olunur.\n- Ödəniş qəbzi və ya Pro alət tələb olunmur.\n\n[[EN]]\n## Assignment goal: Campaign Dashboard\nThis practical assignment is designed for beginners. No ad spend is necessary: use labeled synthetic or cited public data.\n**Example scenario:** Calculate click-through and conversion rates from five fictional rows.\n\n## Free tools and platforms\n- **Google Sheets** — https://sheets.google.com. Create a sheet, name the columns and add at least five fictional rows.\n> No paid subscriptions, ad budgets or paid API keys are required. If a free quota is exhausted, choose a local alternative. Never share passwords, personal data or assets you cannot legally reuse.\n\n## Step-by-step guide\n1. Set up your work folder: Talora / Digital Marketing / Task-9. Reuse your earlier fictional artifacts or create five sample records.\n2. Explain the objective and intended user in one sentence; define what success would look like.\n3. Define CTR, conversion and cost metrics. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n4. Visualize synthetic results. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n5. Document limitations. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n6. Work through the scenario: Calculate click-through and conversion rates from five fictional rows. Document what worked and any limitations.\n7. Complete the main artifact: Campaign dashboard. Verify that a reader can open the PDF/file or shared link; keep the editable source too.\n8. Review all three essential actions, then write a three-to-five sentence conclusion listing tools, sources and improvements.\n\n## A worked example\nCalculate click-through and conversion rates from five fictional rows.\nDo not copy the example unchanged; adapt it to your own fictional scenario and distinguish evidence from assumptions.\n\n## What you must submit\n- **Primary artifact:** Campaign dashboard.\n- **Evidence:** a readable file/link or appropriate PDF, spreadsheet, PNG, SVG, MP4, SRT, source code or project file.\n- **Short report:** three to five sentences about your approach, what you verified and why.\n- **Sources:** citations and usage rights for images, audio or reused text.\n\n## Scoring rubric (100 points)\n- **40 points:** all three core actions are shown in the submitted work.\n- **25 points:** tested, accurate, reproducible result or example.\n- **15 points:** readable structure, proper filenames and export format.\n- **10 points:** privacy, licensing and free-tool rules followed.\n- **10 points:** your explanation and suggested improvements.\n\n## Final checklist\n- Never describe mock metrics as actual campaign results.\n- Test file permissions; never expose credentials or private data.\n- Provide practical evidence, not theory alone.\n- Do not pay for premium features to complete the task.","new_description":"[[AZ]]\nCampaign Dashboard: CTR, conversion və cost göstəricilərini müəyyən et. Sintetik nəticələri dashboard-da göstər. Məhdudiyyətləri qeyd et. Pulsuz alətlər: Google Sheets. Nəticə: Campaign metrics dashboard.\n\n[[EN]]\nCampaign Dashboard: Define CTR, conversion and cost metrics. Visualize synthetic results. Document limitations. Free tools: Google Sheets. Output: Campaign dashboard."},{"slug":"talora-digital-marketing-2026","task_number":10,"title":"Marketing Final Report","old_instructions":"[[AZ]]\n## Məqsəd\nKanal, mesaj və KPI nəticələrini birləşdir ;  Üç prioritet təklif et ;  Sübut və ehtimalları ayır.\n\n## Addım-addım icra\n1. Kanal, mesaj və KPI nəticələrini birləşdir.\n2. Üç prioritet təklif et.\n3. Sübut və ehtimalları ayır.\n4. Nəticəni yoxla, fərziyyələri və məlumat mənbələrini qeyd et.\n\n## Nə təhvil verilməlidir?\nMarketing strategy report. Fayl və ya oxuna bilən link, 3–5 cümləlik izah və istifadə edilən mənbələr.\n\n## Qəbul meyarları\nBütün üç addımın nəticəsi artefaktda görünür, verilən nümunələr təkrar yoxlana bilir, uydurma fakt və icazəsiz şəxsi məlumat yoxdur.\n\n[[EN]]\n## Goal\nCombine channel, message and KPI outputs ;  Propose three next steps ;  Separate evidence from assumptions.\n\n## Step-by-step\n1. Combine channel, message and KPI outputs.\n2. Propose three next steps.\n3. Separate evidence from assumptions.\n4. Verify the result; document assumptions and sources.\n\n## Deliverables\nMarketing strategy report. Submit a readable file/link, a short explanation and credited sources.\n\n## Acceptance criteria\nEvidence supports all three steps, examples can be reviewed, and no fabricated facts or unauthorized personal data are included.","old_description":"[[AZ]]\nKanal, mesaj və KPI nəticələrini birləşdir ;  Üç prioritet təklif et ;  Sübut və ehtimalları ayır.\n\n[[EN]]\nCombine channel, message and KPI outputs ;  Propose three next steps ;  Separate evidence from assumptions.","new_instructions":"[[AZ]]\n## Tapşırığın məqsədi: Marketing Final Report\nBu tapşırıq birinci dəfə bu sahəni öyrənən tələbə üçün praktik işdir. Reklam büdcəsi tələb edilmir: məlumatı sintetik və ya mənbəli olaraq göstər.\n**Nümunə situasiya:** Məhsul, auditoriya, kanal, metrikalar və 3 tövsiyəni təqdimatla yekunlaşdır.\n\n## Hansı pulsuz alətlər lazımdır?\n- **Google Slides** — https://slides.google.com. Bir slaydda bir əsas fikir yerləşdir, sonunda PDF eksport et.\n> Heç bir pullu abunə, reklam büdcəsi və ya API açarı tələb olunmur. Free plan limiti bitdikdə lokal alternativdən istifadə et. Başqa şəxslərin şifrəsini, şəxsi məlumatını və icazəsiz fayllarını paylaşma.\n\n## Addım-addım icra təlimatı\n1. Öz iş qovluğunu yarat: Talora / Digital Marketing / Task-10. Əvvəlki tapşırıqların nəticəsi varsa onlardan istifadə et; yoxdursa 5 sintetik nümunə sətri hazırla.\n2. Bu tapşırığın məqsədini və istifadəçisini bir cümlədə yaz; nümunədə hansı nəticənin uğur sayılacağını müəyyən et.\n3. Kanal, mesaj və KPI nəticələrini birləşdir. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n4. Üç prioritet təklif et. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n5. Sübut və ehtimalları ayır. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n6. Nümunəni işlə: Məhsul, auditoriya, kanal, metrikalar və 3 tövsiyəni təqdimatla yekunlaşdır. Hansı məqamın düzgün işlədiyini və hansı məhdudiyyətin qaldığını ayrıca izah et.\n7. Əsas artefaktı hazırla: Marketing strategy report. Oxuna bilən PDF/fayl və ya paylaşılabilən linki yoxla; redaktə edilən orijinalı da saxla.\n8. Öz işini təkrar yoxla. Üç əsas addımı bitirdiyini göstər; 3–5 cümləlik nəticə, istifadə olunan alətlər və mənbələri qeyd et.\n\n## İşlənmiş nümunə necə görünməlidir?\nMəhsul, auditoriya, kanal, metrikalar və 3 tövsiyəni təqdimatla yekunlaşdır.\nBu nümunəni olduğu kimi kopyalama: öz sintetik ssenarinə uyğun doldur, araşdırdığın faktları və fərziyyələri ayır.\n\n## Nə təhvil verməlisən?\n- **Əsas nəticə:** Marketing strategy report.\n- **Sübut:** oxunan fayl və ya link; uyğun olduqda PDF, cədvəl, PNG, SVG, MP4, SRT, kod və ya layihə faylı.\n- **Qısa hesabat:** 3–5 cümlədə nə etdin, niyə bu üsulu seçdin, nəyi yoxladın?\n- **Mənbələr:** istinadlar, istifadə etdiyin vizual/audio materialın icazəsi.\n\n## Qiymətləndirmə meyarları (100 bal)\n- **40 bal:** Üç əsas fəaliyyətin hər biri real nəticədə görünür.\n- **25 bal:** Nümunə və məntiq yoxlanılıb, nəticə təkrarlana bilir.\n- **15 bal:** Fayl oxunaqlı, düzgün adlandırılıb və bölmələr aydındır.\n- **10 bal:** Məxfilik, müəlliflik və pulsuz istifadə qaydaları gözlənilib.\n- **10 bal:** Öz sözlərinlə yekun və mümkün təkmilləşdirmə izah olunub.\n\n## Göndərməzdən əvvəl yoxla\n- Demo nəticəni real kampaniya nəticəsi adlandırma.\n- Link başqa şəxsə oxu icazəsi verir, amma sənədin içində şəxsi məlumat və şifrə yoxdur.\n- Lazım olan hissələr sadəcə nəzəri cümlələr deyil, təqdim etdiyin real artefaktla sübut olunur.\n- Ödəniş qəbzi və ya Pro alət tələb olunmur.\n\n[[EN]]\n## Assignment goal: Marketing Final Report\nThis practical assignment is designed for beginners. No ad spend is necessary: use labeled synthetic or cited public data.\n**Example scenario:** Present the audience, channel mix, metrics and three evidence-backed recommendations.\n\n## Free tools and platforms\n- **Google Slides** — https://slides.google.com. Use one idea per slide, then export the presentation as PDF.\n> No paid subscriptions, ad budgets or paid API keys are required. If a free quota is exhausted, choose a local alternative. Never share passwords, personal data or assets you cannot legally reuse.\n\n## Step-by-step guide\n1. Set up your work folder: Talora / Digital Marketing / Task-10. Reuse your earlier fictional artifacts or create five sample records.\n2. Explain the objective and intended user in one sentence; define what success would look like.\n3. Combine channel, message and KPI outputs. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n4. Propose three next steps. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n5. Separate evidence from assumptions. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n6. Work through the scenario: Present the audience, channel mix, metrics and three evidence-backed recommendations. Document what worked and any limitations.\n7. Complete the main artifact: Marketing strategy report. Verify that a reader can open the PDF/file or shared link; keep the editable source too.\n8. Review all three essential actions, then write a three-to-five sentence conclusion listing tools, sources and improvements.\n\n## A worked example\nPresent the audience, channel mix, metrics and three evidence-backed recommendations.\nDo not copy the example unchanged; adapt it to your own fictional scenario and distinguish evidence from assumptions.\n\n## What you must submit\n- **Primary artifact:** Marketing strategy report.\n- **Evidence:** a readable file/link or appropriate PDF, spreadsheet, PNG, SVG, MP4, SRT, source code or project file.\n- **Short report:** three to five sentences about your approach, what you verified and why.\n- **Sources:** citations and usage rights for images, audio or reused text.\n\n## Scoring rubric (100 points)\n- **40 points:** all three core actions are shown in the submitted work.\n- **25 points:** tested, accurate, reproducible result or example.\n- **15 points:** readable structure, proper filenames and export format.\n- **10 points:** privacy, licensing and free-tool rules followed.\n- **10 points:** your explanation and suggested improvements.\n\n## Final checklist\n- Never describe mock metrics as actual campaign results.\n- Test file permissions; never expose credentials or private data.\n- Provide practical evidence, not theory alone.\n- Do not pay for premium features to complete the task.","new_description":"[[AZ]]\nMarketing Final Report: Kanal, mesaj və KPI nəticələrini birləşdir. Üç prioritet təklif et. Sübut və ehtimalları ayır. Pulsuz alətlər: Google Slides. Nəticə: Marketing strategy report.\n\n[[EN]]\nMarketing Final Report: Combine channel, message and KPI outputs. Propose three next steps. Separate evidence from assumptions. Free tools: Google Slides. Output: Marketing strategy report."}]$guide_payload$::jsonb);
DO $preflight$
DECLARE matched integer;
BEGIN
 SELECT COUNT(*) INTO matched FROM curriculum_revised c
 CROSS JOIN LATERAL jsonb_array_elements(c.payload) e(item)
 JOIN public.internships i ON i.slug=e.item->>'slug'
 JOIN public.internship_tasks t ON t.internship_id=i.id
   AND t.task_number=(e.item->>'task_number')::integer
   AND t.title=e.item->>'title'
 WHERE t.instructions=e.item->>'old_instructions'
 AND t.description=e.item->>'old_description'
 AND i.slug='talora-digital-marketing-2026';
 IF (SELECT jsonb_array_length(payload) FROM curriculum_revised)<>10 OR matched<>10 THEN
  RAISE EXCEPTION 'Content version mismatch for talora-digital-marketing-2026; matched %',matched;
 END IF;
END; $preflight$;
UPDATE public.internship_tasks t
SET instructions=e.item->>'new_instructions', description=e.item->>'new_description'
FROM curriculum_revised c
CROSS JOIN LATERAL jsonb_array_elements(c.payload) e(item)
JOIN public.internships i ON i.slug=e.item->>'slug'
WHERE i.slug='talora-digital-marketing-2026'
AND t.internship_id=i.id AND t.task_number=(e.item->>'task_number')::integer
AND t.title=e.item->>'title';
DO $verify$
DECLARE matched integer;
BEGIN
 SELECT COUNT(*) INTO matched FROM curriculum_revised c
 CROSS JOIN LATERAL jsonb_array_elements(c.payload) e(item)
 JOIN public.internships i ON i.slug=e.item->>'slug'
 JOIN public.internship_tasks t ON t.internship_id=i.id AND t.task_number=(e.item->>'task_number')::integer
 WHERE t.instructions=e.item->>'new_instructions' AND t.description=e.item->>'new_description'
 AND t.status='published' AND t.is_required AND i.slug='talora-digital-marketing-2026';
 IF matched<>10 THEN RAISE EXCEPTION 'Verification failed after update for talora-digital-marketing-2026: %',matched; END IF;
END; $verify$;
COMMIT;